{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear who attends the vendor meeting (e.g., specific roles such as maintenance engineer, procurement lead, operations manager) and who is responsible for writing the summary.",
      "why_it_matters": "Knowing which roles are involved determines ownership of tasks and where automation or routing rules must be applied."
    },
    {
      "category": "system",
      "gap": "No system is identified for capturing meeting notes, action items, or follow-up tracking (e.g., email, shared document, project management tool).",
      "why_it_matters": "The presence or absence of a structured system directly affects whether automation can extract, store, or route information without manual re-entry."
    },
    {
      "category": "output",
      "gap": "The format and destination of the meeting summary are unspecified—it is unknown whether it is a structured document, an email, or an entry in a tracking system, and who receives it.",
      "why_it_matters": "Output format and distribution determine how downstream automation (e.g., auto-assignment of action items) can be triggered."
    },
    {
      "category": "decision",
      "gap": "There is no description of how action items are prioritized or assigned after the meeting, or what criteria determine whether an action item is accepted, deferred, or rejected.",
      "why_it_matters": "Decision logic is essential for automating triage and assignment workflows without human intervention at every step."
    },
    {
      "category": "exception",
      "gap": "It is unclear what happens when an action item is not completed by its due date—whether there is an escalation path, a reminder process, or a re-negotiation step.",
      "why_it_matters": "Exception handling defines whether the follow-up loop can be automated end-to-end or requires manual intervention at failure points."
    },
    {
      "category": "frequency",
      "gap": "The cadence of vendor meetings and follow-up cycles is not stated (e.g., monthly, quarterly, ad hoc), nor is the expected turnaround time for action item completion.",
      "why_it_matters": "Frequency drives decisions about scheduling automation, SLA monitoring, and the volume of items the system must handle."
    },
    {
      "category": "integration_constraint",
      "gap": "It is unknown whether the vendor has access to any shared platform or whether all communication happens through unstructured channels such as email or phone.",
      "why_it_matters": "If the vendor cannot connect to internal systems, automated data exchange is limited and manual handoffs remain necessary."
    },
    {
      "category": "manual_effort",
      "gap": "The effort involved in producing the summary is not quantified—it is unclear whether this is a brief email or a lengthy structured report requiring significant time.",
      "why_it_matters": "Quantifying manual effort helps prioritize which steps offer the highest automation return on investment."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Which roles from your organization typically attend the vendor meeting, and which specific role is responsible for producing the meeting summary afterward?",
      "targets": ["actor"]
    },
    {
      "id": "Q2",
      "question": "What tool or system is currently used to record meeting notes and track action items—for example, email threads, a shared document, or a dedicated project management platform?",
      "targets": ["system"]
    },
    {
      "id": "Q3",
      "question": "What does the meeting summary look like as a finished output—is it a free-text email, a structured template, or a formal document—and who receives it?",
      "targets": ["output"]
    },
    {
      "id": "Q4",
      "question": "How are action items assigned and prioritized after the meeting—is there a defined process for deciding who owns each item and when it must be completed?",
      "targets": ["decision"]
    },
    {
      "id": "Q5",
      "question": "What happens when an action item is not completed by its agreed deadline—is there a formal escalation path, an automated reminder, or does it rely on someone manually following up?",
      "targets": ["exception"]
    },
    {
      "id": "Q6",
      "question": "How often do these vendor meetings occur, and what is the typical expected turnaround time for resolving the action items that come out of them?",
      "targets": ["frequency"]
    }
  ]
}
